import XCTest
import Foundation
@testable import MediaPreservation
final class ManifestTests:XCTestCase{
 func source(_ types:[Int]=[1],utis:[String]?=nil,live:Bool=false,local:String="fixture",modification:Date?=Date(timeIntervalSince1970:100)) -> MediaSourceSnapshot{MediaSourceSnapshot(localID:local,mediaType:types==[2] ? "video":"image",livePhoto:live,width:100,height:100,creation:Date(timeIntervalSince1970:1),modification:modification,resources:types.enumerated().map{ResourceDescriptor(ordinal:$0.offset,resourceType:$0.element,uti:utis?[$0.offset] ?? ($0.element==2||$0.element==9 ? "public.mpeg-4":"public.jpeg"))})}
 func manifest(_ types:[Int]=[1],utis:[String]?=nil,live:Bool=false)->MediaManifest{MediaManifest(binding:ManifestBinding(accountID:UUID(),deviceID:UUID(),libraryID:UUID()),source:source(types,utis:utis,live:live))}
 func captured(_ input:MediaManifest)->MediaManifest{var m=input;for i in m.resources.indices{m.resources[i].expectedSize=100;m.resources[i].expectedSha256=String(repeating:"a",count:64)};m.state = .completeLocal;return m}
 func store()throws->ManifestStore{let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);addTeardownBlock{try? FileManager.default.removeItem(at:root)};return try ManifestStore(url:root.appendingPathComponent("manifest.sqlite"))}
 func proof(_ m:MediaManifest,count:Int?=nil,protection:String="FULLY_PROTECTED",changed:Bool=false,degraded:Bool=false)throws->ServerManifestProof{let protected=count ?? m.required.count;let resources=m.resources.enumerated().map{i,r -> [String:Any] in ["id":r.id.uuidString,"role":r.descriptor.role.rawValue,"resourceType":r.descriptor.resourceType,"uti":r.descriptor.uti,"required":r.descriptor.required,"resourceClass":r.descriptor.resourceClass.rawValue,"expectedSize":r.expectedSize as Any? ?? NSNull(),"expectedSha256":r.expectedSha256 as Any? ?? NSNull(),"assetId":i<protected ? UUID().uuidString as Any:NSNull(),"cloudVersionId":i<protected ? String(repeating:"b",count:64) as Any:NSNull(),"status":i<protected ? "PROTECTED":"VERIFYING"]};let json:[String:Any]=["id":m.id.uuidString,"manifestVersion":1,"kind":m.source.kind.rawValue,"mediaType":m.source.mediaType,"policy":"PRESERVE_ALL_AVAILABLE","legacy":false,"protection":protection,"requiredCount":m.required.count,"protectedCount":protected,"sourceFingerprint":m.source.fingerprint,"sourceChanged":changed,"reviewRequired":!m.source.shapeComplete,"integrityDegraded":degraded,"manifestFingerprint":String(repeating:"c",count:64),"resources":resources];return try JSONDecoder().decode(ServerManifestProof.self,from:JSONSerialization.data(withJSONObject:json))}
 func testOrdinaryPhotoManifestComplete(){XCTAssertTrue(captured(manifest()).completeLocal)}
 func testOrdinaryVideoManifestComplete(){XCTAssertTrue(captured(manifest([2])).completeLocal)}
 func testLivePhotoRequiresPair(){XCTAssertFalse(manifest([1],live:true).source.shapeComplete);XCTAssertTrue(captured(manifest([1,9],live:true)).completeLocal)}
 func testMissingPairedBytesIncomplete(){var m=captured(manifest([1,9],live:true));m.resources[1].expectedSha256=nil;XCTAssertFalse(m.completeLocal)}
 func testRawRole(){let m=manifest([1],utis:["com.adobe.raw-image"]);XCTAssertEqual(m.source.kind,.raw);XCTAssertEqual(m.resources[0].descriptor.role,.raw)}
 func testRawJPEGRequiresBoth(){var m=captured(manifest([1,4],utis:["com.adobe.raw-image","public.jpeg"]));XCTAssertEqual(m.source.kind,.rawJPEG);m.resources[1].expectedSize=nil;XCTAssertFalse(m.completeLocal)}
 func testEditedPolicyPreservesOriginalRenderedAdjustment(){let m=manifest([1,5,7]);XCTAssertEqual(m.source.kind,.edited);XCTAssertEqual(m.required.count,3);XCTAssertTrue(m.source.shapeComplete)}
 func testMissingAdjustmentFailsFidelity(){XCTAssertFalse(manifest([1,5]).source.shapeComplete)}
 func testAdjustmentIsRequired(){XCTAssertTrue(ResourceDescriptor(ordinal:0,resourceType:7,uti:"public.data").required)}
 func testAdjustmentBaseIsRequired(){XCTAssertTrue(ResourceDescriptor(ordinal:0,resourceType:8,uti:"public.jpeg").required)}
 func testPairedAdjustmentBaseIsRequired(){XCTAssertEqual(ResourceDescriptor(ordinal:0,resourceType:11,uti:"public.mpeg-4").role,.adjustmentBase)}
 func testUnknownResourceRequiresReview(){let m=manifest([1,65535]);XCTAssertFalse(m.source.shapeComplete);XCTAssertTrue(m.resources[1].descriptor.required);XCTAssertEqual(m.state,.unsupported)}
 func testOptionalPhotoProxyDoesNotBlockCompleteness(){var m=captured(manifest([1,19]));m.resources[1].expectedSha256=nil;m.resources[1].expectedSize=nil;XCTAssertTrue(m.completeLocal);XCTAssertEqual(m.required.count,1)}
 func testPreviewNeverSubstitutesOriginal(){XCTAssertFalse(manifest([19]).source.shapeComplete)}
 func testSixteenResourcesBound(){XCTAssertTrue(manifest(Array(repeating:1,count:16)).source.enumerationValid);XCTAssertFalse(manifest(Array(repeating:1,count:17)).source.enumerationValid)}
 func testEmptyManifestRejected(){XCTAssertFalse(manifest([]).source.enumerationValid)}
 func testUTIInjectionRejected(){XCTAssertFalse(ResourceDescriptor(ordinal:0,resourceType:1,uti:"public.jpeg;unsafe").safe)}
 func testSourceModificationChangesFingerprint(){XCTAssertNotEqual(source().fingerprint,source(modification:Date(timeIntervalSince1970:101)).fingerprint)}
 func testLocalIdentifierReuseCannotMaskResourceChange(){XCTAssertNotEqual(source().fingerprint,source([1,9],live:true).fingerprint)}
 func testOrderingDifferenceIsConservative(){XCTAssertNotEqual(source([1,9],live:true).fingerprint,source([9,1],live:true).fingerprint)}
 func testUTIChangeInvalidatesFingerprint(){XCTAssertNotEqual(source().fingerprint,source(utis:["public.png"]).fingerprint)}
 func testFingerprintDeterministic(){XCTAssertEqual(source().fingerprint,source().fingerprint)}
 func testVersionOneAccepted(){XCTAssertEqual(manifest().manifestVersion,1)}
 func testFutureVersionCannotClaimComplete(){let m=MediaManifest(binding:manifest().binding,source:source(),manifestVersion:2);XCTAssertFalse(captured(m).completeLocal);XCTAssertThrowsError(try m.wireMetadata())}
 func testWireOmitsLocalIdentifierAndFilename()throws{let m=manifest();let s=String(decoding:try JSONSerialization.data(withJSONObject:m.wireMetadata()),as:UTF8.self);XCTAssertFalse(s.contains("fixture"));XCTAssertFalse(s.contains("localID"));XCTAssertFalse(s.contains("filename"))}
 func testRawJPEGWireNormalizesJPEGRole()throws{let m=manifest([1,4],utis:["public.jpeg","com.adobe.raw-image"]);let json=try m.wireMetadata();let r=json["resources"] as! [[String:Any]];XCTAssertEqual(r[0]["role"] as? String,"JPEG_COMPANION")}
 func testSameBytesDifferentRolesNotDeduplicated(){let m=captured(manifest([1,9],live:true));XCTAssertNotEqual(m.resources[0].id,m.resources[1].id);XCTAssertEqual(m.resources[0].expectedSha256,m.resources[1].expectedSha256)}
 func testLocalCaptureCannotClaimFullyProtected()async throws{let s=try store();var m=manifest();try await s.insert(m);m.state = .fullyProtected;do{_=try await s.save(m);XCTFail()}catch{}}
 func testClientCannotSetResourceProtection()async throws{let s=try store();var m=manifest();try await s.insert(m);m.resources[0].status="PROTECTED";do{_=try await s.save(m);XCTFail()}catch{}}
 func testStoreSurvivesReopen()async throws{let root=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);defer{try? FileManager.default.removeItem(at:root)};let url=root.appendingPathComponent("m.sqlite"),a=try ManifestStore(url:url),m=manifest();try await a.insert(m);let b=try ManifestStore(url:url);let read=try await b.read(m.id);XCTAssertEqual(read?.source,m.source)}
 func testPartialVerifiedStatePersists()async throws{let s=try store(),base=manifest([1,9],live:true);try await s.insert(base);let m=try await s.save(captured(base));let p=try proof(m,count:1,protection:"PARTIALLY_PROTECTED");let result=try await s.apply(p,to:m.id);XCTAssertEqual(result.state,.partiallyProtected);XCTAssertEqual(result.resources.filter{$0.status=="PROTECTED"}.count,1)}
 func testRetryAllResourcesCompletesProtection()async throws{let s=try store(),base=manifest([1,9],live:true);try await s.insert(base);let m=try await s.save(captured(base));let partial=try await s.apply(proof(m,count:1,protection:"PARTIALLY_PROTECTED"),to:m.id);let complete=try await s.apply(proof(partial),to:m.id);XCTAssertEqual(complete.state,.fullyProtected);XCTAssertEqual(complete.protectedBytes,200)}
 func testServerFullWithoutAllVersionsCannotSpoofFull()async throws{let s=try store(),base=manifest([1,9],live:true);try await s.insert(base);let m=try await s.save(captured(base));let result=try await s.apply(proof(m,count:1),to:m.id);XCTAssertNotEqual(result.state,.fullyProtected)}
 func testAccountHistoryScoped()async throws{let s=try store(),m=manifest();try await s.insert(m);let other=ManifestBinding(accountID:UUID(),deviceID:m.binding.deviceID,libraryID:m.binding.libraryID);let page=try await s.page(binding:other);XCTAssertTrue(page.isEmpty)}
 func testDeviceHistoryScoped()async throws{let s=try store(),m=manifest();try await s.insert(m);let other=ManifestBinding(accountID:m.binding.accountID,deviceID:UUID(),libraryID:m.binding.libraryID);let page=try await s.page(binding:other);XCTAssertTrue(page.isEmpty)}
 func testStaleRevisionRejected()async throws{let s=try store(),m=manifest();try await s.insert(m);_=try await s.save(captured(m));do{_=try await s.save(captured(m));XCTFail()}catch{}}
 func testSourceIdentityImmutable()async throws{let s=try store(),m=manifest();try await s.insert(m);let changed=MediaManifest(id:m.id,binding:m.binding,source:source([1,9],live:true));do{_=try await s.save(changed);XCTFail()}catch{}}
 func testIncompleteLiveNotCleanupEligible()throws{let m=captured(manifest([1,9],live:true));XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m,count:1,protection:"PARTIALLY_PROTECTED"),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testIncompleteRAWNotCleanupEligible()throws{let m=captured(manifest([1,4],utis:["com.adobe.raw-image","public.jpeg"]));XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m,count:1,protection:"PARTIALLY_PROTECTED"),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testCompleteAcceptedManifestEligible()throws{let m=captured(manifest([1,9],live:true));XCTAssertTrue(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testPhysicalFidelityPendingBlocksCleanup()throws{let m=captured(manifest([1,9],live:true));XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:m.source,binding:m.binding,fidelityAccepted:false))}
 func testIntegrityLossRevokesCleanup()throws{let m=captured(manifest());XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m,degraded:true),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testSourceChangedRevokesCleanup()throws{let m=captured(manifest());XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m,changed:true),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testDifferentDeviceRevokesCleanup()throws{let m=captured(manifest());XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:m.source,binding:ManifestBinding(accountID:m.binding.accountID,deviceID:UUID(),libraryID:m.binding.libraryID),fidelityAccepted:true))}
 func testCurrentSourceDifferenceRevokesCleanup()throws{let m=captured(manifest());XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:source([1,9],live:true),binding:m.binding,fidelityAccepted:true))}
 func testUnknownTypeNeverCleanupEligible()throws{let m=captured(manifest([1,65535]));XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
 func testNilModificationNeverCleanupEligible()throws{let m=captured(MediaManifest(binding:manifest().binding,source:source(modification:nil)));XCTAssertFalse(MediaCleanupEligibility.eligible(m,proof:try proof(m),fresh:m.source,binding:m.binding,fidelityAccepted:true))}
}
